def tryf(di, adjacency='orth+diag', moveorder='bottom-right'):
    H,W=len(di),len(di[0])
    cur=[row[:] for row in di]
    objs=objects(di)
    # marker colors keep separate comps; rebuild each pass
    def touched(cellsA, cellsB):
        for (a,b) in cellsA:
            for da in (-1,0,1):
                for db in (-1,0,1):
                    if (da,db)!=(0,0) and (a+da,b+db) in cellsB: return True
        return False
    changed=True
    while changed:
        changed=False
        objs=objects(cur)
        placed={}
        for o,_ in objs:
            comp,_=o;_=_
        # order
        olist=objs
        if moveorder=='br': olist=sorted(olist,key=lambda o:(max(r for r,c in o[0]),max(c for r,c in o[0]),min(c)))
        elif moveorder=='tr': olist=sorted(olist,key=lambda o:(max(r for r,c in o[0]),max(c for r,c in o[0]),max(c)),reverse=True)
        elif moveorder=='tl': olist=sorted(olib=key=lambda o:(min(r for r,c in o[0]),min(c for r,c in o[0]),min(c)), reverse=True)
        newcur=[row[:] for row in cur]
        for comp,col in olist:
            cells=set(comp)
