            h=max(r for r,c in comp)-min(r for r,c in comp)+1
            for cc in reversed(range(W-w+1)):
                cand={(min(r for r,c in comp)+i,cc+j) for i in range(h) for j in range(w)}
                if all(cur[a][b]==0 for a,b in cand):
                    blocked=False
                    if len(objs)>1:
                        oth=set()
                        for oc,o2 in objs:
                            if oc is not None and oc[0]!=cells: oth|=set(o2[0])
                        if touched(cand,oth): blocked=True
                    break
            if not blocked:
                for (a,b) in list(cells): newcur[a][b]=0
                for (a,b) in cand: newcur[a][b]=col
                changed=True
        cur=newcur
    return cur

