                    cells.add((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==g[i][j] and (x,y) not in cells: st.append((x,y))
                objs.append((cells, g[i][j]))
    # process bottom-up (by min row descending)
    order=sorted(range(len(objs)), key=lambda k: min(a for a,_ in objs[k]), reverse=True)
    occupied=set()  # placed cells
    out=[[0]*W for _ in range(H)]
    res=[]
    for k in order:
        cur=objs[k][0]; c=objs[k][1]
        # slide right until collision with placed cells (including diagonal adjacency)
        def collides(cur):
            for a,b in cur:
                nb=(a,b+1)
                if b+1>=W or nb in occupied: return True
            return False
        while not collides(cur):
            cur=[(a,b+1) for a,b in cur]
        occupied|=cur
        res.append((cur,c))
    for cur,c in res:
        for a,b in cur: out[a][b]=c
    return out
